-- ============================================================================
-- find_confusable_lstrm.sql
-- 법령용어(lstrm)는 title이 "법령용어: {용어명}" 뿐이라 출처 법령명이 없습니다.
-- 같은 용어명이 여러 법에서 서로 다르게 정의된 경우, title만으로는 구분이 안 될
-- 수 있습니다. law_010719 때와 같은 패턴이 실제로 존재하는지 확인합니다.
-- ============================================================================

-- [1] 같은 용어명(title)이 여러 chunk로 존재하는 경우 - "다른 법에서 다르게 정의됨" 후보
SELECT title, COUNT(*) AS def_count,
       array_agg(chunk_id ORDER BY chunk_id) AS chunk_ids
FROM legal_chunks
WHERE doc_type = 'lstrm'
GROUP BY title
HAVING COUNT(*) > 1
ORDER BY def_count DESC
LIMIT 50;

