-- [2] 위 [1]에서 나온 것 중, 실제로 정의 내용(content)까지 서로 다른지 확인
--     (내용까지 같으면 단순 중복 적재일 수 있고, 다르면 진짜 "동명이의 법령용어")
--     -- 여기 상위 몇 개 title을 [1] 결과 보고 직접 넣어서 실행하세요. 예시:
-- SELECT chunk_id, title, content
-- FROM legal_chunks
-- WHERE doc_type = 'lstrm' AND title = '법령용어: 사업자'
-- ORDER BY chunk_id;


-- [3] 전체 규모 파악: 총 lstrm 용어 수 대비 "동명이의" 비율
WITH term_groups AS (
    SELECT title, COUNT(*) AS cnt
    FROM legal_chunks
    WHERE doc_type = 'lstrm'
    GROUP BY title
)
SELECT
    COUNT(*) AS total_unique_titles,
    COUNT(*) FILTER (WHERE cnt > 1) AS duplicate_title_count,
    SUM(cnt) FILTER (WHERE cnt > 1) AS chunks_involved_in_duplicates
FROM term_groups;

-- 72551	11518	49540

-- [4] lstrm chunk_id/content 구조 샘플 (title 외에 content에 출처 법령명이 있는지 확인)
SELECT chunk_id, doc_id, title, content
FROM legal_chunks
WHERE doc_type = 'lstrm'
ORDER BY chunk_id
LIMIT 5;

